// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.system.handlerimport timber.log.Timberimport com.roshan.persona.brain.skill.SystemOperationimport com.roshan.persona.common.AppErrorimport com.roshan.persona.common.CorrelationIdimport com.roshan.persona.common.Resultimport com.roshan.persona.system.executor.ResourceCategory/** * NOUS — Battery Saver Handler (Module 10 v2 — Step 10.9). * * Toggles battery saver mode via `PowerManager.setPowerSaveMode`. * * ## Permission * * No special permission required — any app can call `setPowerSaveMode` * (Android 5.0+). The system may still restrict it on some OEM ROMs. * * ## Idempotent execution (Review 2 Elite 1) * * If battery saver is already in the target state, skip the call. * * ## Pre-state capture (Review 2 Fix A) * * Captures the previous on/off state. Undo restores the actual previous state. * * ## Resource category * * Battery saver uses [ResourceCategory.SETTINGS] — no shared hardware contention. * * @see <a href="docs/strategy/module-10-system-strategy-v2.md">§Scope — Battery Saver</a> */class BatterySaverHandler(    private val batterySaverService: BatterySaverService,) : ReversibleHandler<SystemOperation.SetBatterySaver> {    override val id: String = "battery_saver"    override val displayName: String = "Battery Saver Control"    override val requiredPermissions: Set<String> = emptySet()    override val resourceCategory: ResourceCategory = ResourceCategory.SETTINGS    override fun isAvailable(): Boolean = true    override suspend fun execute(operation: SystemOperation.SetBatterySaver): Result<Unit> {        val success = batterySaverService.setOn(operation.enabled)        return if (success) {            Result.Success(Unit, CorrelationId.generate(), 0)        } else {            Result.Failure(                error = AppError.Hardware.Unknown("battery_saver"),                correlationId = CorrelationId.generate(),                durationNanos = 0,            )        }    }    override suspend fun capturePreState(operation: SystemOperation.SetBatterySaver): Any? {        return try {            BatterySaverPreState(wasOn = batterySaverService.isOn())        } catch (t: Throwable) {            Timber.tag("BatterySaverHandler").w("capturePreState failed", t)            null        }    }    override suspend fun restorePreState(operation: SystemOperation.SetBatterySaver, preState: Any?) {        if (preState !is BatterySaverPreState) return        try {            batterySaverService.setOn(preState.wasOn)        } catch (t: Throwable) {            Timber.tag("BatterySaverHandler").w("restorePreState failed", t)        }    }    override suspend fun getCurrentState(): Any? = try {        BatterySaverPreState(wasOn = batterySaverService.isOn())    } catch (t: Throwable) { null }    override suspend fun isAlreadyInTargetState(operation: SystemOperation.SetBatterySaver): Boolean {        return try {            batterySaverService.isOn() == operation.enabled        } catch (t: Throwable) {            false        }    }    override fun describeOperation(operation: SystemOperation.SetBatterySaver): String =        if (operation.enabled) "Battery saver turned on" else "Battery saver turned off"    // ─── Pre-state serialization (audit defect B fix) ─────────────────────    override fun serializePreState(preState: Any?): String? {        if (preState == null) return null        if (preState !is BatterySaverPreState) {            return com.roshan.persona.system.undo.SystemOperationSerializer.serializePreState(preState)        }        return "{\"type\":\"BatterySaverPreState\",\"wasOn\":${preState.wasOn}}"    }    override fun deserializePreState(json: String?): Any? {        if (json == null) return null        val map = try {            com.roshan.persona.system.undo.SystemOperationSerializer.parseJsonObject(json)        } catch (t: Throwable) {            return com.roshan.persona.system.undo.SystemOperationSerializer.deserializePreState(json)        }        return when (map["type"] as? String) {            "BatterySaverPreState" -> BatterySaverPreState(wasOn = (map["wasOn"] as? Boolean) ?: false)            else -> com.roshan.persona.system.undo.SystemOperationSerializer.deserializePreState(json)        }    }    /** Captured pre-state for battery saver (previous on/off). */    data class BatterySaverPreState(val wasOn: Boolean)}
